    bash_cmds = []
    read_paths = {}
    finish_data = None
    tool_results_with_error = 0
    tool_calls_after_error = 0
    in_error_state = False
    writes = 0
    edits = 0

    with open(sj_path) as f:
        for line in f:
            try:
                r = json.loads(line)
                if r.get('role') == 'assistant':
                    for c in r.get('content', []):
                        if c.get('type') == 'toolCall':
                            name = c.get('name', '?')
                            args = c.get('arguments', {})

                            if name == 'bash':
                                cmd = args.get('command', '')[:80]
                                bash_cmds.append(cmd)
                            elif name == 'read':
                                p = args.get('path', '')
                                read_paths[p] = read_paths.get(p, 0) + 1
