import json, os

# Focus on NON-coder, NON-gym sessions for real behavioral patterns
sessions_dir = ".state/sessions/history"
dirs = sorted(os.listdir(sessions_dir), key=lambda d: os.path.getmtime(f"{sessions_dir}/{d}"), reverse=True)[:60]

for d in dirs:
    meta_path = f"{sessions_dir}/{d}/meta.json"
    sj_path = f"{sessions_dir}/{d}/session.jsonl"
    if not os.path.exists(sj_path):
        continue
    try:
        meta = json.load(open(meta_path))
        agent = meta.get('agent', '?')
    except:
        agent = '?'

    # Skip coder (mostly gym) and may (mostly routing)
    if agent in ('coder', 'may', 'scout'):
        continue

    tools = {}
    bash_cmds = []
    read_paths = {}
    writes_edits = []
    finish_summary = ''
    agents_calls = []
    checkpoint_calls = 0

    with open(sj_path) as f:
        for line in f:
            try:
                r = json.loads(line)
                if r.get('role') == 'assistant':
                    for c in r.get('content', []):
                        if c.get('type') == 'toolCall':
                            name = c.get('name', '?')
                            args = c.get('arguments', {})
                            tools[name] = tools.get(name, 0) + 1
                            if name == 'bash':
                                cmd = args.get('command', '')
                                bash_cmds.append(cmd[:80])
                                if cmd.startswith('cat ') and '|' not in cmd and '>' not in cmd:
                                    pass  # counted in tools
                            elif name == 'read':
                                p = args.get('path', '')
                                read_paths[p] = read_paths.get(p, 0) + 1
                            elif name in ('write', 'edit'):
                                writes_edits.append((name, args.get('path', '')[:60]))
                            elif name == 'finish':
                                finish_summary = args.get('summary', '')[:150]
                            elif name == 'agents':
                                agents_calls.append(args.get('action', '') + ':' + args.get('agent', ''))
                            elif name == 'checkpoint':
                                checkpoint_calls += 1
            except:
                pass

    total_ops = sum(tools.values())
    if total_ops < 5:
        continue  # skip trivial sessions

    # Look for interesting patterns
    multi_reads = {p: c for p, c in read_paths.items() if c >= 2}
    bash_cat = sum(1 for c in bash_cmds if c.startswith('cat ') and '|' not in c and '>' not in c)

