        flags.append(f'bash-cat: {bash_cat}')
    if total_ops > 20 and not writes_edits:
        flags.append(f'READ-ONLY ({total_ops} ops, 0 writes)')
    if agents_calls:
        flags.append(f'delegated: {agents_calls}')

    if flags:
        print(f"\n{d.split('/')[-1][-10:]} | {agent:12s} | ops={total_ops:3d}")
